  <title>Pobrecita — Photo Gallery</title>
  <style>
    :root {
      --bg: #0f0f12;
      --panel: #18181d;
      --text: #f2f2f2;
      --muted: #a0a0ac;
      --accent: #e09f3e;
      --accent-2: #9e2a2b;
      --radius: 12px;
      --gap: 18px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.5;
    }

    header {
      padding: 2.5rem 1rem 1.5rem;
      text-align: center;
      background: linear-gradient(180deg, rgba(224,159,62,0.15) 0%, rgba(15,15,18,0) 70%);
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3.5rem);
      letter-spacing: -0.02em;
    }

    header p {
      margin: 0.5rem 0 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 0.6rem;
      padding: 1rem;
    }

    .controls button {
      background: var(--panel);
      color: var(--text);
      border: 1px solid rgba(255,255,255,0.08);
      padding: 0.55rem 1.15rem;
      border-radius: 999px;
      cursor: pointer;
      font-size: 0.95rem;
      transition: background 0.2s, border-color 0.2s, color 0.2s;
    }

    .controls button:hover,
    .controls button.active {
      background: var(--accent);
      color: #1a1200;
      border-color: var(--accent);
      font-weight: 600;
    }

    main {
      max-width: 1200px;
      margin: 0 auto;
      padding: 1rem 1rem 3rem;
    }

    .gallery {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
      gap: var(--gap);
    }

    .card {
      background: var(--panel);
      border-radius: var(--radius);
      overflow: hidden;
      border: 1px solid rgba(255,255,255,0.05);
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
      opacity: 0;
      animation: fadeIn 0.5s ease forwards;
    }

    .card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 28px rgba(0,0,0,0.35);
      border-color: rgba(224,159,62,0.35);
    }

    .card img {
      width: 100%;
      height: 200px;
      object-fit: cover;
      display: block;
      background: #222;
    }

    .card figcaption {
      padding: 0.85rem 1rem;
    }

    .card h3 {
      margin: 0 0 0.25rem;
      font-size: 1rem;
    }

    .card span {
      font-size: 0.8rem;
      color: var(--muted);
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    .empty {
      text-align: center;
      color: var(--muted);
      padding: 3rem 1rem;
      grid-column: 1 / -1;
    }

    .lightbox {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.92);
      display: none;
      align-items: center;
      justify-content: center;
      z-index: 1000;
      padding: 1rem;
      opacity: 0;
      transition: opacity 0.25s ease;
    }

    .lightbox.open {
      display: flex;
      opacity: 1;
    }

    .lightbox-inner {
      position: relative;
      max-width: 900px;
      width: 100%;
      text-align: center;
    }

    .lightbox img {
      max-width: 100%;
      max-height: 80vh;
      border-radius: var(--radius);
      box-shadow: 0 20px 60px rgba(0,0,0,0.5);
      background: var(--panel);
    }

    .lightbox-caption {
      margin-top: 0.75rem;
      color: var(--text);
    }

    .lightbox-close,
    .lightbox-prev,
    .lightbox-next {
      position: absolute;
      background: rgba(255,255,255,0.12);
      border: none;
      color: var(--text);
      width: 44px;
      height: 44px;
      border-radius: 50%;
      cursor: pointer;
      font-size: 1.25rem;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.2s;
    }

    .lightbox-close:hover,
    .lightbox-prev:hover,
    .lightbox-next:hover {
      background: rgba(255,255,255,0.25);
    }

    .lightbox-close { top: -52px; right: 0; }
    .lightbox-prev { left: -52px; top: 50%; transform: translateY(-50%); }
    .lightbox-next { right: -52px; top: 50%; transform: translateY(-50%); }

    footer {
      text-align: center;
      padding: 2rem 1rem;
      color: var(--muted);
      font-size: 0.9rem;
      border-top: 1px solid rgba(255,255,255,0.05);
    }

    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }

    @media (max-width: 640px) {
      .lightbox-prev { left: 8px; top: auto; bottom: -52px; transform: none; }
      .lightbox-next { right: 8px; top: auto; bottom: -52px; transform: none; }
      .lightbox-close { right: 8px; top: -48px; }
    }
  </style>
</head>
<body>
  <header>
    <h1>Pobrecita</h1>
    <p>A self-contained photo gallery.</p>
  </header>

  <div class="controls" role="tablist" aria-label="Filter gallery">
    <button class="active" data-filter="all" role="tab" aria-selected="true">All</button>
    <button data-filter="portraits" role="tab" aria-selected="false">Portraits</button>
    <button data-filter="places" role="tab" aria-selected="false">Places</button>
    <button data-filter="moments" role="tab" aria-selected="false">Moments</button>
    <button data-filter="details" role="tab" aria-selected="false">Details</button>
  </div>

  <main>
    <section class="gallery" id="gallery" aria-live="polite"></section>
  </main>

  <div class="lightbox" id="lightbox" aria-hidden="true" role="dialog" aria-modal="true" aria-label="Photo preview">
    <button class="lightbox-close" aria-label="Close">&times;</button>
    <button class="lightbox-prev" aria-label="Previous photo">&#10094;</button>
    <button class="lightbox-next" aria-label="Next photo">&#10095;</button>
    <div class="lightbox-inner">
      <img id="lightbox-img" src="" alt="" />
      <div class="lightbox-caption" id="lightbox-caption"></div>
    </div>
  </div>

  <footer>
    &copy; Pobrecita Gallery. Built in a single file.
  </footer>

  <script>
    (function () {
      const categories = [
        { id: 'portraits', label: 'Portraits' },
        { id: 'places', label: 'Places' },
        { id: 'moments', label: 'Moments' },
        { id: 'details', label: 'Details' }
      ];

      const titles = {
        portraits: ['Golden Hour', 'Soft Gaze', 'Window Light', 'City Face', 'Quiet Smile', 'Shadow Play'],
        places: ['Morning Market', 'Coastal Road', 'Old Alley', 'Mountain Pass', 'Harbor Lights', 'Empty Square'],
        moments: ['First Dance', 'Rainy Afternoon', 'Sunset Toast', 'Road Trip', 'Birthday Glow', 'Lazy Sunday'],
        details: ['Coffee Rings', 'Woven Textures', 'Dried Flowers', 'Type & Ink', 'Weathered Wood', 'Morning Light']
      };

      function svgImage(seed, hue) {
        const w = 800;
        const h = 600;
        const hue2 = (hue + 35) % 360;
        const hue3 = (hue + 180) % 360;
        const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='${w}' height='${h}' viewBox='0 0 ${w} ${h}'>
          <defs>
            <linearGradient id='g' x1='0%' y1='0%' x2='100%' y2='100%'>
              <stop offset='0%' stop-color='hsl(${hue}, 60%, 55%)'/>
              <stop offset='100%' stop-color='hsl(${hue2}, 55%, 35%)'/>
            </linearGradient>
            <filter id='n' x='0' y='0' width='100%' height='100%'>
              <feTurbulence type='fractalNoise' baseFrequency='0.006' numOctaves='3' seed='${seed}'/>
            </filter>
          </defs>
          <rect width='100%' height='100%' fill='url(#g)'/>
          <rect width='100%' height='100%' filter='url(#n)' opacity='0.22'/>
          <circle cx='${200 + (seed * 137) % 400}' cy='${150 + (seed * 53) % 300}' r='${80 + (seed % 60)}' fill='hsl(${hue3}, 70%, 65%)' opacity='0.25'/>
          <rect x='${(seed * 211) % 500}' y='${(seed * 97) % 350}' width='${120 + (seed % 100)}' height='${80 + (seed % 80)}' fill='rgba(255,255,255,0.12)' transform='rotate(${(seed % 30) - 15} ${(seed * 211) % 500} ${(seed * 97) % 350})'/>
        </svg>`;
        return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
      }

      function generateItems() {
        const items = [];
        let id = 1;
        categories.forEach(cat => {
          const catTitles = titles[cat.id];
          catTitles.forEach((title, i) => {
            const seed = id * 7 + i * 13;
            const hue = (id * 47) % 360;
            items.push({
              id: id++,
              category: cat.id,
              categoryLabel: cat.label,
              title: title,
              src: svgImage(seed, hue),
              alt: `${title} — ${cat.label}`
            });
          });
        });
        return items;
      }

      const gallery = document.getElementById('gallery');
      const lightbox = document.getElementById('lightbox');
      const lightboxImg = document.getElementById('lightbox-img');
      const lightboxCaption = document.getElementById('lightbox-caption');
      const closeBtn = lightbox.querySelector('.lightbox-close');
      const prevBtn = lightbox.querySelector('.lightbox-prev');
      const nextBtn = lightbox.querySelector('.lightbox-next');
      const filterButtons = document.querySelectorAll('.controls button');

      const allItems = generateItems();
      let currentItems = allItems.slice();
      let currentIndex = 0;

      function renderGallery(filter) {
        currentItems = filter === 'all'
          ? allItems.slice()
          : allItems.filter(item => item.category === filter);

        gallery.innerHTML = '';

        if (currentItems.length === 0) {
          gallery.innerHTML = '<p class="empty">No photos in this category yet.</p>';
          return;
        }

        currentItems.forEach((item, index) => {
          const card = document.createElement('figure');
          card.className = 'card';
          card.tabIndex = 0;
          card.setAttribute('role', 'button');
          card.setAttribute('aria-label', `View ${item.title}`);
          card.style.animationDelay = `${index * 0.04}s`;
          card.innerHTML = `
            <img src="${item.src}" alt="${item.alt}" loading="lazy" />
            <figcaption>
              <h3>${item.title}</h3>
              <span>${item.categoryLabel}</span>
            </figcaption>
          `;
          card.addEventListener('click', () => openLightbox(index));
          card.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ') openLightbox(index);
          });
          gallery.appendChild(card);
        });
      }

      function openLightbox(index) {
        currentIndex = index;
        updateLightbox();
        lightbox.classList.add('open');
        lightbox.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
        lightboxImg.focus?.();
      }

      function closeLightbox() {
        lightbox.classList.remove('open');
        lightbox.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
      }

      function updateLightbox() {
        const item = currentItems[currentIndex];
        lightboxImg.src = item.src;
        lightboxImg.alt = item.alt;
        lightboxCaption.textContent = `${item.title} — ${item.categoryLabel}`;
      }

      function nextPhoto() {
        currentIndex = (currentIndex + 1) % currentItems.length;
        updateLightbox();
      }

      function prevPhoto() {
        currentIndex = (currentIndex - 1 + currentItems.length) % currentItems.length;
        updateLightbox();
      }

      filterButtons.forEach(btn => {
        btn.addEventListener('click', () => {
          filterButtons.forEach(b => {
            b.classList.remove('active');
            b.setAttribute('aria-selected', 'false');
          });
          btn.classList.add('active');
          btn.setAttribute('aria-selected', 'true');
          renderGallery(btn.dataset.filter);
        });
      });

      closeBtn.addEventListener('click', closeLightbox);
      nextBtn.addEventListener('click', (e) => { e.stopPropagation(); nextPhoto(); });
      prevBtn.addEventListener('click', (e) => { e.stopPropagation(); prevPhoto(); });
      lightbox.addEventListener('click', (e) => { if (e.target === lightbox) closeLightbox(); });
      document.addEventListener('keydown', (e) => {
        if (!lightbox.classList.contains('open')) return;
        if (e.key === 'Escape') closeLightbox();
        if (e.key === 'ArrowRight') nextPhoto();
        if (e.key === 'ArrowLeft') prevPhoto();
      });

      renderGallery('all');
    })();
  </script>
</body>
</html>
